// Normalize the incoming QC request. Expected body:
// { video_path: '/renders/client_v3.mp4', client: 'acme', model: 'kling-3.0', min_duration: 4 }
const body = $input.first().json.body ?? $input.first().json;

const videoPath = String(body.video_path ?? '').trim();
if (!videoPath) {
  throw new Error('video_path is required (absolute path or URL to the rendered file)');
}

return [{
  json: {
    video_path: videoPath,
    client: body.client ?? 'unspecified',
    model: body.model ?? 'unspecified',
    min_duration_sec: Number(body.min_duration ?? 4),
    min_width: Number(body.min_width ?? 1280),
    min_fps: Number(body.min_fps ?? 24),
    checked_at: new Date().toISOString(),
  },
}];

// Score the ffprobe output against the QC contract.
// ffprobe failures (missing file, unreadable container) reach this node with empty stdout:
// the Probe node runs with onError=continueRegularOutput, so its failure lands here as data.
const execOut = $input.first().json;
const stdout = execOut.stdout ?? '';
if (!stdout.trim()) {
  const errObj = execOut.error;
  const errText = typeof errObj === 'string' ? errObj : (errObj && errObj.message ? errObj.message : (execOut.message ?? ''));
  const stderrText = execOut.stderr ? String(execOut.stderr).trim().split('\n')[0] : '';
  const exitText = execOut.exitCode ? 'ffprobe exited with code ' + execOut.exitCode : '';
  const detail = [exitText, errText, stderrText].filter(Boolean).join(': ');
  return [{ json: { verdict: 'fail', reasons: ['could not probe the render - ' + (detail || 'file missing or unreadable')] } }];
}
let probe;
try {
  probe = JSON.parse(stdout);
} catch (e) {
  return [{ json: { verdict: 'fail', reasons: ['ffprobe output could not be parsed: ' + e.message] } }];
}

const norm = $('Normalize Request').first().json;
const fmt = probe.format ?? {};
const videoStream = (probe.streams ?? []).find((s) => s.codec_type === 'video') ?? {};
const audioStream = (probe.streams ?? []).find((s) => s.codec_type === 'audio');

const reasons = [];

const duration = Number(fmt.duration ?? videoStream.duration ?? 0);
if (duration <= 0) reasons.push('unreadable duration (' + duration + 's) - file may be truncated or not a video');
else if (duration < norm.min_duration_sec) reasons.push(`duration ${duration.toFixed(2)}s < required ${norm.min_duration_sec}s`);

const width = Number(videoStream.width ?? 0);
const height = Number(videoStream.height ?? 0);
if (!width || !height) reasons.push('no video stream found');
else if (width < norm.min_width) reasons.push(`width ${width}px < required ${norm.min_width}px`);

const fpsRaw = videoStream.avg_frame_rate ?? '0/1';
const [num, den] = fpsRaw.split('/').map(Number);
const fps = den ? num / den : 0;
if (fps <= 0) reasons.push('unreadable frame rate');
else if (fps < norm.min_fps) reasons.push(`frame rate ${fps.toFixed(2)}fps < required ${norm.min_fps}fps`);

const verdict = reasons.length === 0 ? 'pass' : 'fail';

return [{
  json: {
    verdict,
    reasons,
    file: norm.video_path,
    client: norm.client,
    model: norm.model,
    checked_at: norm.checked_at,
    probe_summary: {
      duration_sec: Number(duration.toFixed(2)),
      resolution: width && height ? `${width}x${height}` : 'n/a',
      fps: Number(fps.toFixed(2)),
      video_codec: videoStream.codec_name ?? 'n/a',
      pixel_format: videoStream.pix_fmt ?? 'n/a',
      audio: audioStream ? audioStream.codec_name : 'none (typical for silent AI-generated renders)',
    },
  },
}];
